contract SimpleBank{

    uint public balance;

    function deposit(uint _amount)public {
        balance= balance + _amount;
    }

    function withdraw( uint _amount)public {
        balance = balance - _amount;

    }
     
    function getBalance()public view returns (uint){
        return balance;
    }
